-- =============================================================================
-- ORDER SERVICE (PostgreSQL) - smms_order_service
-- Tables: orders, order_items, payments
-- order_code used as reference in customer-service & inventory-service
-- product_sku & product_name match product-service
-- customer_id / cashier_id reference identity-service UUIDs
-- =============================================================================

-- customer_id & cashier_id match identity-service User.id (UUID)
-- Note: In Order entity, customerId/cashierId are UUID columns but are 
-- "logical" foreign keys (no DB-level FK since cross-service)

-- sub_total = quantity * unit_price; product_sku & product_name match product-service

-- payment amount = order final_amount; payment_method from enum

SELECT setval('order_items_id_seq', (SELECT MAX(id) FROM order_items));
SELECT setval('payments_id_seq', (SELECT MAX(id) FROM payments));
